import{d as c,B as g,o as r,c as n,K as o,k as u,F as d,G as i,e as m,g as p,_ as y,j as a,a as s,a0 as b}from"./chunks/framework.BGabeMLJ.js";const f=["src","alt"],v={inheritAttrs:!1},w=c({...v,__name:"VPImage",props:{image:{},alt:{}},setup(l){return(e,h)=>{const t=g("VPImage",!0);return e.image?(r(),n(d,{key:0},[typeof e.image=="string"||"src"in e.image?(r(),n("img",o({key:0,class:"VPImage"},typeof e.image=="string"?e.$attrs:{...e.image,...e.$attrs},{src:u(p)(typeof e.image=="string"?e.image:e.image.src),alt:e.alt??(typeof e.image=="string"?"":e.image.alt||"")}),null,16,f)):(r(),n(d,{key:1},[i(t,o({class:"dark",image:e.image.dark,alt:e.image.alt},e.$attrs),null,16,["image","alt"]),i(t,o({class:"light",image:e.image.light,alt:e.image.alt},e.$attrs),null,16,["image","alt"])],64))],64)):m("",!0)}}}),k=y(w,[["__scopeId","data-v-eb0caff4"]]),A=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/architecture.md","filePath":"getting-started/architecture.md"}'),H={name:"getting-started/architecture.md"},N=Object.assign(H,{setup(l){const e={light:"/images/components/FLAME_analysis_bright.png",dark:"/images/components/FLAME_analysis_dark.png"};return(h,t)=>(r(),n("div",null,[t[0]||(t[0]=a("h1",{id:"architecture",tabindex:"-1"},[s("Architecture "),a("a",{class:"header-anchor",href:"#architecture","aria-label":'Permalink to "Architecture"'},"​")],-1)),t[1]||(t[1]=a("p",null,[s("FLAME consists of two parts: one central "),a("strong",null,"Hub"),s(" and one "),a("strong",null,"Node"),s(" at every participating site. The Hub coordinates, the Nodes compute. Patient data stays at the site, only analysis code travels to the data and only aggregated results travel back.")],-1)),i(k,{image:e}),t[2]||(t[2]=b('<p>The graphic gives a rough overview of the execution flow of an analysis. The individual services are listed on the <a href="./components.html">Components</a> page.</p><h2 id="hub-and-node" tabindex="-1">Hub and Node <a class="header-anchor" href="#hub-and-node" aria-label="Permalink to &quot;Hub and Node&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Hub</th><th>Node</th></tr></thead><tbody><tr><td>Runs</td><td>once, centrally</td><td>once per site (hospital, university, ...)</td></tr><tr><td>Purpose</td><td>coordination</td><td>execution on local data</td></tr><tr><td>Holds</td><td>users, projects, analysis code, analysis images, results</td><td>the site&#39;s data stores and running analyses</td></tr><tr><td>Sees patient data</td><td>no</td><td>yes, inside the site only</td></tr><tr><td>Used by</td><td>researchers and administrators</td><td>node administrators and data stewards</td></tr></tbody></table><h3 id="hub" tabindex="-1">Hub <a class="header-anchor" href="#hub" aria-label="Permalink to &quot;Hub&quot;">​</a></h3><p>The Hub is the single place researchers work with. Its services:</p><ul><li><strong>User Interface</strong> to create projects and analyses, review them and download results.</li><li><strong>Core</strong> as the main backend, managing all resources and triggering commands and events.</li><li><strong>Authentication and authorization</strong> (Authup), organized in one <em>realm</em> per organization.</li><li><strong>Analysis building</strong>, which combines the approved code with a master image into a container image.</li><li><strong>Container image registry</strong> (Harbor) with a separate, private project for every node.</li><li><strong>Message Broker</strong>, which relays the messages nodes send to each other.</li><li><strong>Storage</strong> for code, intermediate results and final results.</li></ul><h3 id="node" tabindex="-1">Node <a class="header-anchor" href="#node" aria-label="Permalink to &quot;Node&quot;">​</a></h3><p>A Node is installed on a Kubernetes cluster inside the network of a site. Its services:</p><ul><li><strong>Node UI</strong> to configure data stores and to start, stop and monitor analyses.</li><li><strong>Hub API Adapter</strong>, the backend of the Node UI and the connection to the Hub.</li><li><strong>Pod Orchestration</strong>, which starts every analysis in its own isolated pod.</li><li><strong>Data access through an API gateway</strong> (Kong), which exposes exactly the data stores of a project to its analyses.</li><li><strong>Message Broker</strong> and <strong>Result Service</strong>, the node side of the communication with other nodes and the Hub.</li></ul><h2 id="lifecycle-of-an-analysis" tabindex="-1">Lifecycle of an analysis <a class="header-anchor" href="#lifecycle-of-an-analysis" aria-label="Permalink to &quot;Lifecycle of an analysis&quot;">​</a></h2><ol><li><strong>Project:</strong> a researcher creates a project in the Hub and selects the nodes that should take part. Every selected node approves or rejects the project.</li><li><strong>Data stores:</strong> at every approving site, an administrator or data steward connects the requested data (a FHIR server or an S3 bucket) to the project as a data store.</li><li><strong>Analysis:</strong> the researcher creates an analysis within the project, uploads the code and selects a master image with the required dependencies.</li><li><strong>Review:</strong> the administrator of every node can download and read the code, and approves or rejects the analysis.</li><li><strong>Build and distribution:</strong> after the approvals, the Hub builds one container image from master image and code and pushes it into the registry project of each node.</li><li><strong>Execution:</strong> every node pulls its image. The node administrator starts the analysis in the Node UI. The analysis runs in an isolated pod and can only reach the data stores of its own project.</li><li><strong>Aggregation:</strong> the analyzing nodes send their results to the node with the aggregator role, which combines them. For iterative methods such as federated learning this repeats over several rounds.</li><li><strong>Results:</strong> the aggregator submits the final result to the Hub storage, where the researcher downloads it.</li></ol><p>The same steps from the perspective of each role are described in the <a href="./../guide/user/index.html">User</a> and <a href="./../guide/admin/index.html">Admin</a> guides.</p><h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><ul><li><strong>Nodes connect to the Hub, never the other way round.</strong> All connections are initiated by the Node as outbound HTTPS. A Node does not have to be reachable from the internet.</li><li><strong>Nodes do not talk to each other directly.</strong> Messages and intermediate results are relayed through the Hub.</li><li><strong>What is relayed is encrypted end to end.</strong> Messages and intermediate results are encrypted for the receiving nodes with the node key pairs, so the Hub cannot read them.</li><li><strong>Analyses are isolated.</strong> An analysis container has no internet access and no access to other services of the Node. It only reaches its project&#39;s data, the message broker and the result service through a dedicated proxy.</li></ul><p>Details are documented in <a href="./../guide/deployment/node-security.html">Security &amp; Operations</a>.</p><h2 id="where-data-lives" tabindex="-1">Where data lives <a class="header-anchor" href="#where-data-lives" aria-label="Permalink to &quot;Where data lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Location</th><th>Leaves the site</th></tr></thead><tbody><tr><td>Patient data (FHIR resources, files)</td><td>data stores of the site</td><td>no</td></tr><tr><td>Analysis code</td><td>Hub storage, and inside the analysis image</td><td>yes, it is distributed to the nodes</td></tr><tr><td>Analysis image</td><td>Hub registry, pulled by the nodes</td><td>yes, it is distributed to the nodes</td></tr><tr><td>Messages and intermediate results</td><td>relayed and stored by the Hub, end-to-end encrypted</td><td>yes, readable only by the receiving nodes</td></tr><tr><td>Local intermediate results and checkpoints</td><td>storage of the node</td><td>no</td></tr><tr><td>Final results</td><td>Hub storage</td><td>yes, downloadable by the researcher</td></tr></tbody></table><p>Because final results leave the federation, an analysis must only return aggregated, non-identifying values. This is what the code review by the node administrators is for.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>Hub and Node are both deployed with Helm charts on Kubernetes. See the <a href="./../guide/deployment/index.html">Deployment guide</a>.</p>',20))]))}});export{A as __pageData,N as default};
